fillPaymentSelectors=function(scope){if(!scope)return;const account=scope.querySelector('[name="expenseAccount"]'),card=scope.querySelector('[name="expenseCard"]'),accountValue=account?.value,cardValue=card?.value;if(account){account.innerHTML='<option value="">Selecione uma conta</option>'+ACCOUNTS.map(item=>`<option value="${item.id}">${esc(item.name)}</option>`).join('');if(ACCOUNTS.some(item=>item.id===accountValue))account.value=accountValue}if(card){card.innerHTML='<option value="">Selecione um cartão</option>'+CARDS.map(item=>`<option value="${item.id}">${esc(item.name)}</option>`).join('');if(CARDS.some(item=>item.id===cardValue))card.value=cardValue}}
syncExpensePaymentFields=function(scope=document){scope.querySelectorAll('.expense-payment-fields').forEach(box=>{fillPaymentSelectors(box);const method=box.querySelector('[name="expensePaymentMethod"]')?.value||'direct';box.classList.toggle('credit-card-payment',method==='credit_card');box.querySelector('.expense-account-field').hidden=method==='credit_card';box.querySelector('.expense-card-field').hidden=method!=='credit_card';if(method==='credit_card'){const date=box.closest('form').querySelector('[name="date"],[name="entryDate"]')?.value,card=box.querySelector('[name="expenseCard"]')?.value;if(date&&card)box.querySelector('[name="expenseDueDate"]').value=cardPaymentDate(date,card)}})}
