const stockSettlementSubmitBase=$('#stockEntryForm').onsubmit;$('#stockEntryForm').onsubmit=async function(event){const itemId=$('#stockEntryItemPicker').dataset.selectedId,originalId=editingStockEntryId,status=this.elements.expensePaymentStatus.value,paidDate=this.elements.expensePaidDate.value,date=this.elements.entryDate.value;await stockSettlementSubmitBase.call(this,event);if($('#stockEntryDialog').open)return;let movementId=originalId;if(!movementId){const {data}=await db.from('inventory_movements').select('id').eq('inventory_item_id',itemId).eq('movement_type','entry').gte('occurred_at',`${date}T00:00:00`).lte('occurred_at',`${date}T23:59:59`).order('created_at',{ascending:false}).limit(1).maybeSingle();movementId=data?.id}if(!movementId)return;const {error}=await db.rpc('set_inventory_entry_settlement',{p_movement_id:movementId,p_payment_status:status,p_settled_on:status==='settled'?paidDate:null});if(error)return toast(error.message||'Entrada salva, mas a data de pagamento não foi atualizada.');await loadData();showView('estoque')};
$('#newFinancialBtn').addEventListener('click',()=>{const today=localDate(new Date());$('#financialForm').elements.expensePaidDate.value=today;syncExpensePaymentFields($('#financialForm'))});
$('#stockEntryBtn').addEventListener('click',()=>requestAnimationFrame(()=>{const form=$('#stockEntryForm');form.elements.expensePaidDate.value=form.elements.entryDate.value;syncExpensePaymentFields(form)}));
const financialEntriesDatesBase=financialEntries;financialEntries=function(){return financialEntriesDatesBase().map(entry=>entry.forecast?{...entry,due_on:entry.occurred_on,settled_on:null,payment_status:'planned'}:entry)};
$('#dateLabel').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'});async function bootstrap(){const {data,error}=await db.auth.getSession();if(error||!data.session)return showLogin();await enter(data.session.user)}db.auth.onAuthStateChange(e=>{if(e==='SIGNED_OUT')showLogin()});bootstrap();
